    "answer": "농경·목축과 말·주옥·모피",
    "explanation": "정답 근거\n부여는 송화강 유역 평야를 기반으로 농경·목축을 했고 말·주옥·모피가 경제 단서다.\n\n보기 비교\n소금·어물 공납과 가족 공동 무덤은 옥저, 단궁·과하마·반어피와 책화는 동예, 철 생산과 교역은 삼한 중 변한과 연결된다.\n\n기억 연결\n부여는 평야의 농경·목축과 말·주옥·모피를 한 묶음으로 잡는다.",
