    "question": "한강 유역을 둘러싼 백제 성왕과 신라 진흥왕의 관계 변화를 바르게 설명한 것은?",
    "answer": "연합하여 한강 유역 회복을 추진했으나 이후 대립했고 성왕은 관산성 전투에서 전사했다",
    "explanation": "정답 근거\n성왕은 진흥왕과 연합하여 한강 유역 회복을 추진했지만 이후 신라와 대립하였다. 성왕은 관산성 전투에서 전사했다.\n\n보기 비교\n대가야 병합은 진흥왕의 업적이며 성왕이 지휘한 것이 아니다. 한성을 공격하여 개로왕을 전사시킨 왕은 고구려 장수왕이다. 황산벌은 백제 말 계백의 전투이므로 성왕의 관산성 전투와 구별한다.\n\n기억 연결\n같은 두 나라라도 관계가 바뀐다. 성왕·진흥왕의 연합 → 한강을 둘러싼 대립 → 관산성 순서로 잡는다.",
    "source": "학습 노트 §6 성왕 · 요약 자료 기반 자체 제작 문제(공식 기출 아님)."
