    "subject": "한국사",
    "question": "통일 신라 지방군 10정의 배치에 대한 설명으로 옳은 것은?",
    "answer": "9주에 배치하되 한주에는 2정을 두었다",
    "explanation": "정답 근거: 10정은 9주에 배치하되 한주에 2정을 두어 모두 10정이 된 통일 신라의 지방군이다.\n\n보기 비교: 9주에 한 정씩이면 9정이며, 10위는 발해 중앙군이다. 5소경은 지방 행정 거점이지 이 군사 배치의 기준이 아니다.\n\n기억 연결: 9주+한주 추가 1정=10정으로 숫자를 풀이한다.",
    "source": "추가노트 §3 군사 · 요약 자료 기반 자체 제작 문제(공식 기출 아님)."
