    "answer": "당과 친선 관계를 맺고 신라도를 개설했으며 당의 제도·문물을 받아들였다",
    "explanation": "정답 근거: 문왕은 당과 친선 관계를 유지하고 당의 제도·문물을 수용했으며 신라와 상설 교통로인 신라도를 개설했다. 연호는 대흥이다.\n\n보기 비교: 등주 공격은 무왕, 해동성국은 선왕, 마진·태봉은 궁예의 국호 변화다.\n\n기억 연결: 문왕은 신라도·대흥·제도 정비로 표시한다.",
