    "explanation": "정답 근거: 927년 공산 전투에서는 왕건이 견훤에게 패배했고, 930년 고창 전투에서는 왕건이 후백제에 승리했다.\n\n보기 비교: 두 전투는 후삼국의 고려·후백제 대결이며 발해·거란 전투가 아니다. 935년은 견훤 귀순과 신라 항복, 936년은 통일이다.\n\n기억 연결: 공산은 왕건 패배, 고창은 왕건 승리로 방향을 반대로 외우지 않는다.",
