    "subject": "한국사",
    "question": "발해의 주민 구성과 중앙 제도에 대한 설명으로 옳은 것은?",
    "answer": "주민은 고구려인과 말갈인이었고, 당의 제도를 받아들여 3성 6부를 두었다",
    "explanation": "정답 근거: 발해의 주민은 지배층의 중심인 고구려인과 다수의 말갈인으로 이루어졌다. 중앙에는 당의 제도를 받아들여 3성 6부를 두었지만, 명칭과 운영에는 고유한 특색을 유지하였다.\n\n보기 비교: 거란은 발해의 서쪽에서 성장해 926년 발해를 멸망시킨 세력으로, 발해 주민의 중심이 아니다. 집사부는 통일 신라 중앙 행정의 중심 기관으로, 발해의 제도가 아니다.\n\n기억 연결: 발해 사회는 '고구려인 + 말갈인'과 '당 제도 수용 + 고유 전통 유지'라는 두 개의 더하기로 기억한다.",
