    "explanation": "정답 근거\n요약표는 황룡사 9층 목탑을 “선덕 여왕, 자장의 건의 → 고려 때 몽골의 침입으로 소실”로 정리한다.\n\n보기 비교\n황룡사 9층 목탑을 건의한 승려는 원효가 아니라 자장이고, 몽골 침입으로 불타 지금은 남아 있지 않다. 돌을 벽돌 모양으로 다듬어 쌓은 탑은 분황사 모전 석탑이다. 신문왕 때 세운 쌍탑은 감은사지 3층 석탑이다.\n\n기억 연결\n선덕 여왕 때 신라 불탑 두 개를 함께 기억한다: 분황사 모전 석탑과 황룡사 9층 목탑. 황룡사 탑은 “나무라서 불에 타 사라졌다”.",
