    "explanation": "정답 근거\n요약표는 통일 신라의 불탑으로 경주 감은사지 3층 석탑(신문왕 때 건립, 쌍탑), 경주 불국사 3층 석탑(무구정광대다라니경 발견), 불국사 다보탑, 양양 진전사지 3층 석탑(기단부에 조각), 화순 쌍봉사 철감선사탑(선종의 영향)을 든다.\n\n보기 비교\n진전사지 3층 석탑은 기단부에 조각이 있는 석탑이며 벽돌 전탑이 아니다. 무구정광대다라니경은 다보탑이 아니라 불국사 3층 석탑(석가탑)에서 발견되었다. 철감선사탑은 승려의 사리를 모신 승탑으로, 선종 유행의 산물이며 쌍탑이 아니다.\n\n기억 연결\n감은사 = 신문왕이 아버지 문무왕을 기려 완성한 절, 탑은 동서 두 개(쌍탑). 불국사에는 석가탑과 다보탑이 마주 서 있다.",
