    "subject": "한국사",
    "question": "다음 신라 하대의 왕을 즉위한 순서대로 나열한 것은?\n가. 원성왕\n나. 흥덕왕\n다. 문성왕\n라. 헌덕왕",
    "answer": "가 → 라 → 나 → 다",
    "explanation": "정답 근거: 신라 하대에는 독서삼품과를 마련한 원성왕 → 김헌창의 난이 일어난 헌덕왕 → 장보고가 청해진을 설치한 흥덕왕 → 장보고가 암살된 문성왕 순으로 즉위하였고, 이후 진성여왕에 이른다.\n\n보기 비교: 헌덕왕을 원성왕보다 앞에 두면 독서삼품과보다 김헌창의 난이 먼저 일어난 것이 되어 틀리다. 문성왕을 흥덕왕보다 앞에 두면 청해진 설치보다 장보고의 암살이 먼저가 되어 틀리다.\n\n기억 연결: 왕 이름보다 사건으로 잇는다. 원성왕(독서삼품과) → 헌덕왕(김헌창의 난) → 흥덕왕(청해진 설치) → 문성왕(장보고 암살) → 진성여왕(원종·애노의 난).",
