    "explanation": "정답 근거: 혜공왕 때 진골 귀족 대공이 난을 일으켜 귀족의 반발이 터져 나왔고, 혜공왕이 피살되면서 신라 중대가 끝나고 하대가 시작되었다.\n\n보기 비교: 김흠돌의 난은 신문왕이 즉위한 직후 장인이 일으킨 난으로, 진압 뒤 오히려 왕권이 강화된 중대 초의 사건이다. 국학 설치와 9주 5소경 정비도 신문왕의 업적이다. 정전 지급은 성덕왕, 서시·남시 설치는 효소왕의 일이다.\n\n기억 연결: 중대의 꼬리를 “신문 → 효소 → 성덕 → 효성 → 경덕 → 혜공”으로 두고 혜공왕에 “대공의 난 → 왕 피살 → 중대 끝”을 붙인다. 중대의 시작(김흠돌)과 끝(대공)이 모두 진골 귀족의 난이라는 대비가 기억의 고리다.",
