    "answer": "청해진의 군사력을 바탕으로 신무왕의 즉위를 도왔으나, 뒤를 이은 문성왕 때 암살되었다",
    "explanation": "정답 근거: 희강왕·민애왕·신무왕이 잇달아 바뀐 왕위 쟁탈전에서 장보고는 청해진의 군사력으로 신무왕의 즉위를 도왔고, 그 뒤를 이은 문성왕 때 암살되었다.\n\n보기 비교: 김헌창의 난은 장보고가 청해진을 받기 전 헌덕왕 때의 사건이며 장보고가 진압한 것이 아니다. 장보고는 왕을 세우는 데 개입한 지방 세력이었을 뿐 스스로 왕위에 오른 적이 없다. 원종과 애노의 난은 장보고가 죽은 뒤인 진성여왕 때의 농민 봉기이므로 시기부터 맞지 않는다.\n\n기억 연결: “희강·민애·신무”는 왕위 쟁탈전으로 짧게 스쳐 간 세 왕이고, 그 다음 문성왕에서 장보고가 죽는다. 장보고는 “왕을 세운 지방 세력이지 왕이 된 사람은 아니다”로 못 박아 둔다.",
