    "explanation": "정답 근거: 진성여왕 때 향가집 삼대목이 편찬되고, 사벌주에서 원종과 애노가 농민 봉기를 일으켰으며, 최치원이 시무 10여 조를 올렸다. 적고적의 난도 같은 왕 때의 농민 봉기다.\n\n보기 비교: 김헌창의 난은 헌덕왕, 독서삼품과는 원성왕, 청해진 설치는 흥덕왕, 국학 설치는 신문왕의 일이다. 이 가운데 하나라도 섞인 묶음은 진성여왕 때로 볼 수 없다. 적고적의 난 자체는 진성여왕 때이지만 신문왕의 국학과 함께 묶인 보기는 성립하지 않는다.\n\n기억 연결: 진성여왕에는 세 갈래를 붙인다. 문화는 삼대목, 농민 봉기는 원종·애노와 적고적, 개혁 건의는 최치원의 시무 10여 조다. 농민이 들고일어나는 왕은 하대 끝의 진성여왕, 진골 지방관이 난을 일으킨 왕은 하대 앞의 헌덕왕이다.",
