    "explanation": "정답 근거: 백제 금동 대향로는 부여 능산리 절터에서 나왔다. 뚜껑에는 신선이 사는 산의 모습이, 몸체에는 연꽃이 표현되어 도교 요소와 불교 요소가 함께 나타난다.\n\n보기 비교: 공주 무령왕릉은 중국 남조의 영향을 받은 벽돌무덤으로, 무덤의 주인을 알려 주는 지석이 나왔지만 금동 대향로가 나온 곳은 아니다. 금동 대향로에는 유교 경전 구절이 새겨져 있지 않다.\n\n기억 연결: 백제의 도교 문화는 능산리 금동 대향로와 산수무늬 벽돌, 고구려의 도교 문화는 강서대묘 사신도로 짝지어 기억한다.",
    "source": "08강 고대(문화 1) 086~087쪽 · 문화유산 판별 · 자체 제작 문제(공식 기출 아님)."
