    "answer": "한성기 서울 석촌동 계단식 돌무지무덤 — 웅진기 공주 무령왕릉 벽돌무덤",
    "explanation": "정답 근거: 한성에 도읍하던 때의 서울 석촌동 무덤은 돌을 계단처럼 쌓은 돌무지무덤으로 고구려 무덤 양식과 통한다. 웅진으로 옮긴 뒤의 공주 무령왕릉은 중국 남조의 영향을 받은 벽돌무덤이며, 무덤 주인을 적은 지석이 나왔다.\n\n보기 비교: 두 무덤의 시기를 맞바꾼 연결은 도읍이 옮겨 간 순서부터 뒤집은 것이다. 석촌동 무덤은 굴식 돌방무덤이 아니고, 돌무지덧널무덤은 신라 경주의 무덤 양식이므로 백제 웅진기와 묶이지 않는다.\n\n기억 연결: 백제 무덤은 도읍을 따라 옮겨 간다. 한성—석촌동 돌무지무덤(고구려와 닮음), 웅진—무령왕릉 벽돌무덤(중국 남조·지석)이다. 돌무지덧널무덤은 신라 경주라고 따로 떼어 둔다.",
