    "explanation": "정답 근거: 갈돌과 갈판은 곡식이나 열매를 갈아 먹을 수 있게 만드는 신석기의 조리 도구이고, 반달 돌칼은 곡식의 이삭을 베는 청동기의 수확 도구다.\n\n보기 비교: 두 도구의 시대를 맞바꾼 연결은 농경이 신석기에 시작되고 벼농사가 청동기에 퍼진 순서와 맞지 않는다. 갈돌·갈판은 사냥 도구가 아니며, 신석기에 옷을 만드는 데 쓴 도구는 가락바퀴와 뼈바늘이다.\n\n기억 연결: 도구를 시대에 못 박는다. 갈돌·갈판과 가락바퀴·뼈바늘은 신석기, 반달 돌칼은 청동기다. 갈아서 쓰는 살림 도구는 신석기, 이삭을 베는 도구는 청동기로 나눈다.",
