    "explanation": "정답 근거: 사진 속 탑은 익산 미륵사지 석탑으로, 백제 무왕 때 세웠고 지금 남아 있는 석탑 가운데 가장 오래되었다. 목탑의 짜임을 돌로 옮겨 놓아 층마다 기둥과 얇은 지붕돌이 나무 건물처럼 보인다.\n\n보기 비교: 경주 불국사 다보탑은 통일 신라의 이형 석탑이고, 경주 분황사 모전 석탑은 통일 전 신라 선덕 여왕 때의 탑이며, 화순 쌍봉사 철감선사탑은 통일 신라 하대의 승탑이다. 셋 다 백제 탑이 아니고 현존하는 가장 오래된 석탑도 아니다.\n\n기억 연결: 너른 절터에 홀로 선 큰 석탑이 층마다 기둥과 얇은 지붕돌로 짜여 있으면 목탑 양식의 미륵사지다. 지명이 곧 나라라 익산은 백제, 경주는 신라·통일 신라, 화순은 통일 신라 하대다. 계단과 기둥이 있는 이형 탑은 다보탑, 돌을 벽돌처럼 다듬은 탑은 분황사로 갈라 둔다.",
