    "answer": "경주 불국사 3층 석탑(석가탑)",
    "explanation": "정답 근거: 무구정광대다라니경이 발견된 탑은 경주 불국사 3층 석탑, 곧 석가탑이다. 통일 신라의 탑으로 장식이 거의 없이 반듯하게 줄어드는 3층 석탑이다.\n\n보기 비교: 같은 절 마당에 있는 경주 불국사 다보탑도 통일 신라의 탑이지만 계단과 기둥을 짜 올린 이형 석탑이다. 경주 감은사지 동·서 3층 석탑은 통일 신라 신문왕 때의 쌍탑이고, 부여 정림사지 5층 석탑은 백제의 탑이다.\n\n기억 연결: 불국사의 두 탑은 사진에서 생김새로 가른다. 계단·기둥·난간이 있으면 다보탑, 장식 없이 단정한 3층이면 석가탑이고 무구정광대다라니경은 석가탑에서 나왔다. 지명 앵커는 경주가 신라·통일 신라, 부여가 백제다.",
    "source": "08강 고대(문화 1) 087쪽 불상과 불탑 · 사진 판별 · 자체 제작 문제(공식 기출 아님) · 사진: 국가유산청 국가유산포털, 공공누리 제1유형."
