    "answer": "정혜 공주 묘는 굴식 돌방무덤이고 정효 공주 묘는 벽돌무덤이다",
    "explanation": "정답 근거: 정혜 공주 묘는 굴식 돌방무덤이고, 정효 공주 묘는 벽돌무덤이다.\n\n보기 비교: 둘을 맞바꾼 보기는 성립하지 않는다. 입구가 없는 돌무지덧널무덤은 신라의 무덤이고, 계단식 돌무지무덤은 고구려 장군총과 백제 석촌동의 무덤이므로 발해 공주 묘와 맞지 않다. 정혜 공주 묘에서는 돌사자상이 나왔고 정효 공주 묘에는 벽화도 남아 있다.\n\n기억 연결: 나라 앵커는 발해다. 정혜는 굴식 돌방무덤에 모줄임천장과 돌사자상으로 고구려를 잇고, 정효는 벽돌무덤과 벽화로 당의 영향을 보인다.",
