    "explanation": "정답 근거: 신라는 일본에 배 만드는 기술과 둑 쌓는 기술을 전했고, 그 흔적으로 '한인의 연못'이라는 이름이 남았다.\n\n보기 비교: 백제는 오경박사와 아직기·왕인·노리사치계를 통해 학문과 불교를 전했다. 고구려는 담징·혜자·혜관을 통해 종이와 먹, 불교를 전했다. 발해는 남북국 시대에 일본의 하쿠호 문화에 영향을 주었다.\n\n기억 연결: 나라 앵커에 기술을 붙인다. 신라는 배와 둑, 곧 조선술과 축제술이며 그 이름이 한인의 연못이다.",
    "source": "09강 고대(문화 2) 099쪽 과학 기술·건축·고분·일본 전파 · 요약 자료 기반 자체 제작 문제(공식 기출 아님)."
