    "subject": "한국사",
    "question": "이자겸의 난이 일어난 계기와 난이 수습된 방식을 바르게 연결한 것은?",
    "answer": "국왕 측근이 이자겸 제거를 꾀하다 실패함 — 인종이 척준경을 회유해 이자겸을 제거함",
    "explanation": "정답 근거: 인종의 측근 세력이 이자겸을 제거하려다 실패하자 이자겸이 척준경과 함께 난을 일으켰다. 이후 인종이 척준경을 회유해 이자겸을 제거했고, 척준경도 탄핵을 받아 쫓겨났다.\n\n보기 비교: 금의 사대 요구는 이자겸이 권력을 잡은 뒤 받아들인 것으로, 난의 계기가 아니다. 김부식이 관군을 이끌고 진압한 것은 묘청이 서경에서 일으킨 난이다.\n\n기억 연결: 이자겸의 난은 측근의 제거 시도 실패 → 이자겸·척준경의 난 → 척준경 회유와 이자겸 제거 → 척준경 축출, 묘청의 난은 김부식의 진압으로 두 난의 수습 방식을 구별한다.",
