    "explanation": "정답 근거: 정중부·이의방 등은 보현원에서 정변을 일으켜 의종을 폐하였다.\n\n보기 비교: 인종은 이자겸의 난·묘청의 난 때의 왕이다. 광종은 노비안검법·과거제, 경종은 시정 전시과의 왕이다.\n\n기억 연결: 의종–보현원 정변–폐위. 뒤에 김보당이 이 의종의 복위를 꾀한다.",
