    "subject": "한국사",
    "question": "여진과의 관계에서 일어난 일을 순서대로 나열한 것은?\n가. 별무반 편성\n나. 금의 사대 요구 수용\n다. 동북 9성 반환\n라. 동북 9성 축조",
