    "subject": "한국사",
    "question": "원 간섭기에 원이 고려에서 징발한 특산물과 고려에 전해진 몽골풍의 예를 바르게 연결한 것은?",
    "answer": "징발한 특산물 — 금·은·인삼 / 몽골풍 — 변발·호복",
