    "explanation": "정답 근거: 최영이 홍산에서 왜구를 물리친 뒤, 최무선이 진포에서 화포로 왜구의 배를 불태웠다. 진포에서 패한 왜구가 내륙으로 들어오자 이성계가 황산에서 크게 이겼고, 이후 정지가 관음포에서 왜구를 격파하였다.\n\n보기 비교: 최영의 홍산 대첩은 최무선의 진포 대첩보다 먼저 일어났다. 관음포 전투는 황산 대첩 뒤에 정지가 왜구를 격파한 싸움이므로 황산 대첩보다 앞설 수 없다.\n\n기억 연결: 우왕 때 최영(홍산) → 최무선(진포) → 이성계(황산) → 정지(관음포), 이어서 창왕 때 박위(쓰시마섬 토벌)로 기억한다.",
