    "explanation": "정답 근거: 우왕 때 명의 철령위 설치 통보를 계기로 최영과 요동 정벌을 단행하였다.\n\n보기 비교: 박위의 쓰시마섬 토벌은 창왕, 과전법 실시는 공양왕, 전민변정도감 설치는 공민왕 때다.\n\n기억 연결: 우왕 = 왜구 격퇴(홍산·진포·황산·관음포) + 요동 정벌 + 위화도 회군.",
    "source": "12강 고려(외교) 135쪽 고려의 멸망 · 요약 자료 기반 자체 제작 문제(공식 기출 아님)."
