    "question": "(가) 왕의 재위 기간에 있었던 사실로 옳은 것은?\n\n[수업 대화]\n교사: (가) 왕 때 왕실의 외척이 권력을 쥐고 난을 일으켰어요.\n학생 A: 경원 이씨 가문의 인물이 척준경과 함께 일으킨 난이죠?\n학생 B: 왕이 척준경을 회유해서 그 인물을 제거했다고 배웠어요.",
    "answer": "묘청이 서경에서 국호를 대위라 하고 난을 일으켰다.",
    "explanation": "정답 근거: 경원 이씨 이자겸이 척준경과 난을 일으켰고, 왕이 척준경을 회유해 이자겸을 제거했으므로 (가) 왕은 인종이다. 인종 때 묘청이 서경에서 국호를 대위, 연호를 천개라 하고 난을 일으켰다.\n\n보기 비교: 윤관의 여진 정벌과 동북 9성 축조는 예종 때다. 보현원 무신 정변으로 폐위된 왕은 의종이고, 그 의종의 복위를 꾀한 김보당의 난은 명종 때 일어났다.\n\n기억 연결: 숙예인의명 → 숙종 별무반, 예종 9성, 인종 이자겸·묘청, 의종 보현원 정변, 명종 김보당·조위총·망이·망소이·김사미·효심.",
    "source": "고려 10~12강 기반 기출형(자료 제시) 자체 제작 문제(공식 기출 아님)."
