    "question": "(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?\n\n[연표 설명]\n(가) 왕실의 외척 이자겸이 척준경과 함께 난을 일으켰다.\n(나) 공주 명학소 주민들이 들고일어나자 조정이 명학소를 충순현으로 올려 달래려 하였다.",
