    "question": "(가) 왕의 재위 기간에 있었던 사실로 옳은 것은?\n\n[수업 대화]\n교사: (가) 왕 때 명이 철령 이북 땅에 철령위를 설치하겠다고 알려 왔어요.\n학생 A: 그래서 최영이 요동 정벌을 추진했지요.\n학생 B: 이성계는 4불가론을 내세우며 반대했어요.",
