    "explanation": "정답 근거: 서경 천도에 반대한 개경파의 대표로 경주 김씨이며 유교와 신라 계승 의식을 가진 '이 인물'은 김부식이다. 김부식은 관군을 이끌고 서경에서 일어난 묘청의 난을 진압하였다.\n\n보기 비교: 서경 유수로서 무신 정권에 맞서 난을 일으킨 인물은 조위총이다. 이자겸과 함께 난을 일으킨 인물은 척준경이다. 별무반을 이끌고 여진을 정벌한 인물은 윤관이다. 살수에서 수의 대군을 크게 물리친 인물은 고구려의 을지문덕으로, 고려보다 앞선 시대의 싸움이다.\n\n기억 연결: 서경파 = 묘청·정지상·불교·풍수지리설·고구려 계승·금 정벌 / 개경파 = 김부식·유교·신라 계승·금 사대 인정 → 김부식이 묘청의 난 진압. 살수 대첩은 고구려가 수의 침입을 막아 낸 싸움이다.",
    "source": "고려 10~12강 기반 기출형(자료 제시) 자체 제작 문제(공식 기출 아님)."
