    "answer": "음서로 관직에 나아가고 대농장을 소유하였다.",
    "explanation": "정답 근거: 원 간섭기에 도평의사사와 정방을 장악하고, 공민왕의 개혁 때 억압 대상이 된 '이 세력'은 권문세족이다. 권문세족은 음서로 관직에 나아가고 대농장을 소유하였다.\n\n보기 비교: 홍건적과 왜구를 물리치며 성장한 것은 최영·이성계 등 신흥 무인 세력이다. 풍수지리설을 내세워 서경 천도를 추진한 것은 인종 때 묘청 등 서경 세력이다. 과거로 새로 진출해 개경 문벌과 대립한 것은 문벌 사회가 흔들릴 때의 지방 출신 세력이다. 서원과 향약을 기반으로 향촌에서 세력을 넓힌 것은 조선의 사림이다.\n\n기억 연결: 지배층 흐름 → 문벌(과거·음서·외척) → 무신 → 권문세족(도평의사사·정방·음서·대농장) → 공민왕이 억압하고 신진 사대부를 등용 → 신흥 무인 성장. 조선에서는 훈구에 이어 사림이 서원·향약을 발판으로 성장하였다.",
    "source": "고려 10~12강 기반 기출형(자료 제시) 자체 제작 문제(공식 기출 아님)."
