    "id": "ancientstyle-hist-20260915-009",
    "subject": "한국사",
    "question": "밑줄 그은 '이 나라'에 대한 설명으로 옳은 것은?\n\n[수업 대화]\n교사: 오늘 배울 '이 나라'는 송화강 유역의 넓은 평야에 자리 잡았어요.\n학생 A: 왕 아래에 마가·우가·저가·구가가 있었어요.\n학생 B: 그들이 사출도를 나누어 다스렸다고 배웠어요.",
    "answer": "도둑질한 자에게 훔친 물건의 열두 배를 갚게 하였다.",
