    "subject": "한국사",
    "question": "(가) 왕의 재위 기간에 있었던 사실로 옳은 것은?\n\n[가상 인터뷰]\n기자: 즉위한 뒤 어떤 연호를 쓰셨나요?\n(가) 왕: '영락'이라는 연호를 사용하였소.\n기자: 서쪽으로는 어디까지 나아가셨나요?\n(가) 왕: 거란과 후연을 공격하여 요동과 만주 지역으로 세력을 넓혔소.",
