    "question": "(가) 왕의 재위 기간에 있었던 사실로 옳은 것은?\n\n[답사 계획서]\n답사지: 웅진 시기 (가) 왕의 무덤\n확인할 점 1: 중국 남조의 영향을 받은 벽돌무덤의 구조\n확인할 점 2: 무덤의 주인이 누구인지 알려 준 지석",
