    "explanation": "정답 근거: 웅진 시기에 중국 남조의 영향을 받은 벽돌무덤을 남기고, 지석으로 무덤 주인이 밝혀진 (가) 왕은 백제 무령왕이다. 무령왕은 지방의 22담로에 왕족을 파견해 지방 통제를 강화하고 중국 남조의 양과 교류했다.\n\n보기 비교: 신라 소지 마립간과 혼인 동맹을 맺은 왕은 동성왕, 관산성 전투에서 전사한 왕은 성왕, 6좌평·16관등과 공복을 정한 왕은 고이왕이다.\n\n기억 연결: 무령왕 → 웅진 시기, 22담로 왕족 파견, 양과 교류, 무령왕릉(벽돌무덤·지석). 이름이 비슷한 무왕은 익산 미륵사다.",
