    "question": "(가), (나) 사이의 시기에 있었던 사실로 옳은 것은?\n\n[연표 설명]\n(가) 백제가 한성을 잃은 뒤 도읍을 웅진으로 옮겼다.\n(나) 백제가 도읍을 사비로 옮기고 국호를 남부여로 고쳤다.",
