    "question": "(가) 나라의 문화유산으로 옳은 것은?\n\n[수업 대화]\n학생 A: (가)의 아직기는 일본에 한자를 전했어요.\n학생 B: 왕인은 『천자문』과 『논어』를 전했어요.\n교사: 노리사치계는 불경과 불상을 전했지요.",
