    "answer": "국학을 설치하여 유교 경전을 가르쳤다.",
    "explanation": "정답 근거: 관료전을 지급하고 녹읍을 폐지했으며, 진골 귀족을 누르고 6두품 설총을 중용하여 「화왕계」를 받은 (가) 왕은 신문왕이다. 신문왕은 중앙에 국학을 세우고 박사와 조교를 두어 유교 경전을 가르치게 하였다.\n\n보기 비교: 외사정을 파견해 지방관을 감찰한 것은 문무왕 때이다. 백성에게 정전을 지급한 것은 성덕왕 때이다. 독서삼품과는 원성왕이 국학 학생의 유교 경전 이해 수준을 평가해 관리 선발에 참고한 제도이다.\n\n기억 연결: 신문왕이 학교(국학)를 세우고, 원성왕이 시험(독서삼품과)을 만들었다. 신문왕 → 김흠돌의 난 진압 → 관료전·녹읍 폐지 → 국학 → 6두품 설총 중용.",
