    "answer": "집사부 시중의 권한을 키워 왕권을 강화하였다.",
    "explanation": "정답 근거: 옛 삼국 땅에 3주씩 9주를 두고 그 아래 군·현을 설치했으며, 5소경으로 수도의 치우침을 보완하고, 상수리 제도로 지방 세력을 견제한 '이 나라'는 통일 신라이다. 통일 신라는 집사부와 시중을 중심으로 왕권을 강화하였고, 상대등과 화백 회의의 기능은 약해졌다.\n\n보기 비교: 제가 회의는 고구려, 사출도는 부여, 도병마사는 고려의 제도이다. 통일 신라의 감찰 기관은 사정부와 외사정이다.\n\n기억 연결: 통일 신라 = 집사부·시중(중앙) + 9주·5소경·군현·상수리(지방) + 9서당·10정(군사) + 사정부·외사정(감찰). 신라 말에는 반대로 시중이 약해지고 상대등이 강해진다.",
