    "subject": "한국사",
    "question": "(가) 국가의 경제 상황으로 옳은 것은?\n\n[수업 대화]\n교사: (가)의 농업 모습을 발표해 볼까요?\n학생 A: 밭농사에서 조·보리·콩을 돌려 짓는 2년 3작이 행해졌어요.\n학생 B: 말기에는 목화씨가 들어와 처음으로 재배에 성공했어요.",
