    "question": "(가) 국가의 경제 상황으로 옳은 것은?\n\n[한국사 웹 드라마 기획안]\n제목: 개경 저잣거리 이야기\n1화: 나라가 운영하는 서적점과 다점에 손님이 몰리다\n2화: 곡식 값이 치솟자 상평창이 나서서 물가를 조절하다",
