    "subject": "한국사",
    "question": "(가) 국가의 경제 상황으로 옳은 것은?\n\n[답사 계획서]\n주제: (가)의 도읍에서 찾는 경제 이야기\n· 시전 거리: 경시서가 상인들의 상행위를 감독하던 곳\n· 화폐 전시관: 우리나라 최초의 금속 화폐인 건원중보 살펴보기",
