    "subject": "한국사",
    "question": "밑줄 그은 '이 행정 구역'에 대한 설명으로 옳은 것은?\n\n[답사 계획서]\n답사지: 공주 명학소 터\n· 무신 집권기에 망이·망소이가 이곳 주민을 이끌고 봉기함\n· 조정이 한때 이곳을 충순현으로 올려 주민을 달램\n탐구 질문: 명학소와 같은 '이 행정 구역'의 주민은 어떤 대우를 받았을까?",
