    "question": "(가) 기구에 대한 설명으로 옳은 것은?\n\n[한국사 웹 드라마 기획안]\n제목: 황제를 칭한 왕의 민생 정책\n1화: 쌍기의 건의를 받아들여 과거제를 실시하다\n2화: 억울하게 노비가 된 사람을 조사해 양인으로 풀어 주다\n3화: 왕이 새로운 구제 기구 (가)을/를 설치하다",
