    "question": "고려의 혜민국과 구제도감이 한 일을 바르게 연결한 것은?",
    "answer": "혜민국 — 병자에게 의약품 제공 / 구제도감 — 재해 때 임시로 백성 구제",
    "explanation": "정답 근거: 혜민국은 서민의 질병을 치료하고 병자에게 의약품을 제공한 기구다. 구제도감(구급도감)은 각종 재해가 일어났을 때 백성을 구제하려고 임시로 설치한 기구다.\n\n보기 비교: 두 기구의 역할을 서로 바꾸어 붙인 연결은 틀리다. 두 기구에 같은 역할을 붙인 연결은 의약을 맡은 혜민국과 재해 때만 둔 임시 기구 구제도감의 차이를 놓친 것이다.\n\n기억 연결: 혜민국 = 약, 구제도감·구급도감 = 재해 때 임시.",
