    "subject": "한국사",
    "question": "(가)에 들어갈 내용으로 가장 적절한 것은?\n\n[수업 대화]\n교사: 고려 가족 제도의 특징을 말해 볼까요?\n학생 A: 여성이 재혼하는 일이 비교적 자유로웠어요.\n학생 B: 딸과 아들을 구분하지 않고 태어난 순서대로 호적에 적었어요.\n교사: 맞아요. 그 밖에도 (가) 같은 모습이 있었지요.",
