    "question": "(가) 인물의 활동으로 옳은 것은?\n\n[답사 계획서]\n· 주제: 고려 말 삼은(三隱) 가운데 한 사람인 (가)의 발자취\n· 장소: 충청남도 서천 문헌서원\n· 조사 내용: 이곡의 아들로 고려와 원의 과거에 모두 합격함, 시와 산문을 엮은 『목은집』을 남김",
