    "question": "다음 장면에 등장하는 왕에 대한 설명으로 옳은 것은?\n\n[역사 드라마 대본]\nS#12. 개경 궁궐\n왕: 짐이 궁궐 안에 청연각과 보문각을 세우고 학사를 두어 경전을 강론하게 하였소.\n신하: 폐하, 윤관이 여진을 몰아내고 쌓은 동북 9성을 여진에게 돌려주자는 논의가 일고 있사옵니다.",
