    "subject": "한국사",
    "question": "다음 역사서에 대한 설명으로 옳은 것은?\n\n['이달의 책' 소개]\n· 편찬: 고려 인종의 명을 받아 김부식 등이 편찬함\n· 구성: 본기·연표·지·열전\n· 특징: 유교적 합리주의 사관에 따라 서술하였고, 신라를 계승하였다는 의식이 드러남",
    "answer": "현존하는 우리나라의 역사서 가운데 가장 오래되었다.",
    "explanation": "정답 근거: 인종의 명으로 김부식 등이 편찬하고, 본기·연표·지·열전으로 구성되었으며 유교적 합리주의 사관과 신라 계승 의식이 드러난 역사서는 『삼국사기』다. 『삼국사기』는 현존하는 우리나라 역사서 가운데 가장 오래되었다.\n\n보기 비교: 동명왕에 관한 장편 서사시로 고구려 계승 의식을 담은 것은 이규보의 「동명왕편」이다. 남북국이라는 용어를 처음 쓴 것은 조선 후기 유득공의 『발해고』다. 승려들의 전기를 모은 것은 무신 집권기 각훈의 『해동고승전』이다.\n\n기억 연결: 『삼국사기』 = 김부식·인종 = 현존 최고 + 기전체 + 유교적 합리주의 + 신라 계승.",
    "source": "14강 고려(문화 I) 159쪽 역사서의 편찬 · 요약 자료 기반 자체 제작 문제(공식 기출 아님)."
