    "id": "goryeoculture-hist-20260915-026",
    "subject": "한국사",
    "question": "(가)~(라)에 들어갈 내용으로 옳은 것은?\n\n[한국사 학술 강좌 — 역사서로 읽는 우리 역사]\n제1강 『7대실록』: (가)\n제2강 『삼국사기』: (나)\n제3강 『해동고승전』: (다)\n제4강 『사략』: (라)",
    "answer": "(가) - 고려 초기에 편찬되었으나 지금은 전하지 않는다",
    "explanation": "정답 근거: 『7대실록』은 『고금록』, 『구삼국사』, 고려 왕조 실록과 함께 고려 초기에 편찬된 역사서로, 지금은 전하지 않는다.\n\n보기 비교: 불교사를 중심으로 민간 설화와 야사를 기록한 것은 『삼국사기』가 아니라 일연의 『삼국유사』다. 정통과 대의명분을 중시하는 성리학적 사관은 『해동고승전』이 아니라 이제현의 『사략』이다. 동명왕의 장편 서사시로 고구려 계승을 드러낸 것은 『사략』이 아니라 이규보의 「동명왕편」이다.\n\n기억 연결: 고려 초기 역사서(실록·『구삼국사』·『7대실록』·『고금록』) = 지금은 전하지 않음 → 현존 최고는 『삼국사기』.",
    "source": "14강 고려(문화 I) 159쪽 역사서의 편찬 · 요약 자료 기반 자체 제작 문제(공식 기출 아님)."
