    "subject": "한국사",
    "question": "(가) 왕의 재위 시기에 있었던 사실로 옳은 것은?\n\n[한국사 웹 드라마 기획안]\n제목: 황제를 꿈꾼 (가) 왕\n1화: 광덕·준풍이라는 독자적 연호를 쓰다\n2화: 노비안검법을 시행하여 호족 세력을 누르다\n3화: 개경에 귀법사를 세우고 균여를 주지로 모시다",
    "answer": "승과를 실시하여 합격한 승려에게 승계를 주었다.",
